"Uçağa tıklayınca uçuş detayı açılır (rapor, 3B izleme, notlar, video ve resimler); sahada montajdaki uçak montaj detayına gider. \"Düzenle\" ile fırlatma sistemi ve log. Görev bittiğinde tüm uçuşların raporu hazırsa görev \"Rapor Tamamlandı\" olur.": "Un clic sur l'avion ouvre le détail du vol (rapport, suivi 3D, notes, vidéos et images) ; l'avion en assemblage sur le terrain ouvre son détail d'assemblage. “Modifier” donne accès au système de lancement et au journal. À la fin de la mission, si le rapport de tous les vols est prêt, la mission passe à “Rapport terminé”.",
