"Her satırdaki “Yükle” ile telefonunuzdan fotoğraf ya da PDF seçebilirsiniz. Yüklenen evrak İnsan Kaynakları’na iletilir.": "Avec « Télécharger » sur chaque ligne, vous pouvez sélectionner une photo ou un PDF depuis votre téléphone. Le document téléchargé est transmis aux Ressources humaines.",
