  "Oynatılabilir uçuş logu yok. Önce ": "Aucun journal de vol rejouable. Téléversez d'abord un .bin / .tlog dans ",
  "Araçlar › Uçuş Logu Analizi": "Outils › Analyse des journaux de vol",
  " bölümünden bir .bin / .tlog yükleyin (analizi tamamlanmış loglar listelenir).": " (seuls les journaux dont l'analyse est terminée sont listés).",
  "Uçuş loglarına erişim için Araçlar ya da Saha Yönetimi yetkisi gerekir.": "L'accès aux journaux de vol nécessite l'autorisation Outils ou Gestion terrain.",
  "Kareler önbellekte; hemen açılır": "Images en cache ; ouverture immédiate",
  "Görev {c}": "Mission {c}",
  "Ara: dosya adı, dron, pilot, konum, görev kodu…": "Rechercher : nom de fichier, drone, pilote, lieu, code mission…",
  "↻ Yenile": "↻ Actualiser",
  "Sisteme yüklenmiş ArduPilot .bin / .log ya da MAVLink .tlog kayıtlarından biri 3B dünyada aynen oynatılır; kontrol sizde değildir. Dünyanın merkezi kaydın kalkış (ilk ARM) noktasıdır.": "Un des enregistrements ArduPilot .bin / .log ou MAVLink .tlog téléversés est rejoué tel quel dans le monde 3D ; vous n'avez pas le contrôle. Le centre du monde est le point de décollage (premier ARM) de l'enregistrement.",
  "Önce bir uçuş logu seçin": "Sélectionnez d'abord un journal de vol",
  "Kayıttan oynatma oturumu açıldı": "Session de relecture ouverte",
  "Log açılamadı; analizi tamamlanmış bir .bin/.tlog seçin": "Journal impossible à ouvrir ; choisissez un .bin/.tlog dont l'analyse est terminée",
  "Dünya kaydın kalkış noktası etrafında kurulur (pist seviyesi = kalkış irtifası); çarpışma denetimi kapalıdır. Prosedürel kipte arazi gerçek araziyle örtüşmez; gerçek kipte kalkış noktasının çevresi gerçek yükseklik ve uydu görüntüsüyle kurulur.": "Le monde est construit autour du point de décollage de l'enregistrement (niveau de piste = altitude de décollage) ; la détection de collision est désactivée. En mode procédural le terrain ne correspond pas au réel ; en mode réel les environs du décollage sont construits avec l'altitude réelle et l'imagerie satellite.",
  "▶ Oynat": "▶ Lire",
  "Kayıt sunucuda bir kez ayrıştırılır ve önbelleğe alınır; SITL ve Mission Planner köprüsü açılmaz.": "Le journal est analysé une fois sur le serveur et mis en cache ; ni SITL ni le pont Mission Planner ne sont ouverts.",
