  "Harita verileri (OSM) alınıyor…": "Récupération des données carte (OSM)…",
  "Arazi planı alınıyor…": "Récupération du plan de terrain…",
  "Gerçek arazi · yükseklik {a}…{b} m · ev {h} m MSL": "Terrain réel · altitude {a}…{b} m · base {h} m MSL",
  "{b} bina · {f} orman · {w} su · {r} pist": "{b} bâtiments · {f} forêts · {w} eaux · {r} pistes",
  "OSM verisi alınamadı: binalar/orman/su gösterilmiyor ({e})": "Données OSM indisponibles : bâtiments/forêts/eau non affichés ({e})",
  "Gerçek kipte seçili merkezin çevresi gerçek yükseklik, uydu görüntüsü ve OpenStreetMap binalarıyla kurulur; veriler ilk kullanımda indirilip sunucuda önbelleklenir.": "En mode réel, les environs du centre choisi sont construits à partir de l'altitude réelle, d'images satellite et des bâtiments OpenStreetMap ; les données sont téléchargées à la première utilisation et mises en cache sur le serveur.",
  "Prosedürel dünya: tohumlu rastgele arazi, binalar ve ağaçlar.": "Monde procédural : terrain, bâtiments et arbres aléatoires (graine).",
  "Gövde": "Cellule",
  "Delta kanat": "Aile delta",
  "Caymaz V3: ürettiğimiz uçağın STEP modelinden · Delta kanat: arkadan itişli uçan kanat": "Caymaz V3 : issu du modèle STEP de notre avion · Aile delta : aile volante à hélice propulsive",
  "Google 3B (fotogerçekçi)": "Google 3D (photoréaliste)",
  "Google 3B (fotogerçekçi) · ev {h} m MSL": "Google 3D (photoréaliste) · base {h} m MSL",
  "Google 3B karoları yükleniyor… %{p}": "Chargement des tuiles 3D Google… {p} %",
  "Google 3B verisi alınamadı: {e} → prosedürele düşüldü": "Données 3D Google indisponibles : {e} → repli sur le monde procédural",
  "Google 3B kipinde çevre Google Photorealistic 3D Tiles ile fotogerçekçi kurulur (binalar ve ağaçlar karoların içinde); karolar tarayıcıya doğrudan Google’dan gelir, sunucuda önbelleklenmez; atıf zorunludur. Ev irtifası açık yükseklik verisinden alınır.": "En mode Google 3D, l’environnement est construit de façon photoréaliste à partir des Google Photorealistic 3D Tiles (bâtiments et arbres inclus dans les tuiles) ; les tuiles arrivent au navigateur directement depuis Google et ne sont pas mises en cache sur le serveur ; l’attribution est obligatoire. L’altitude de la base provient de données d’élévation ouvertes.",
  "yükleniyor %{p}": "chargement {p} %",
  "Google 3B yer ofseti {o} m (karo yüzeyi ↔ ev irtifası)": "Décalage du sol Google 3D {o} m (surface des tuiles ↔ altitude de la base)",
  "Dron tipi için görsel gövde: dahili modeller her zaman vardır; sistemdeki STEP/GLB/OBJ dosyaları ya da yüklediğiniz model seçilince tarayıcıda GLB'ye dönüştürülür.": "Cellule visuelle pour le type de drone : les modèles intégrés sont toujours disponibles ; les fichiers STEP/GLB/OBJ du système ou un modèle importé sont convertis en GLB dans le navigateur à la sélection.",
  "Model": "Modèle",
