  "GÖKTUNGU akışı: GUIDED → ARM → NAV_TAKEOFF; dron hedef irtifaya yükselir.": "Séquence GÖKTUNGU : GUIDED → ARM → NAV_TAKEOFF ; le drone monte à l'altitude cible.",
