  "Şimdi PIN kodunuzu girin": "Saisissez maintenant votre PIN", "Hoş geldiniz": "Bienvenue", "Yüz doğrulanamadı": "Le visage n'a pas pu être vérifié", "Yüz doğrulandı · PIN kodunuzu girin": "Visage vérifié · saisissez votre PIN",
  "Yüz tanıtma": "Enregistrement du visage", "Mevcut şifreniz": "Votre mot de passe actuel", "İkinci taramayı başlat": "Lancer le second scan", "Başla": "Commencer", "İkinci tarama": "Second scan",
  "Farklı ışık ve açılarda ikinci bir tarama tanımayı daha güvenilir yapar. Gözlük takıyorsanız bu kez çıkarabilirsiniz.": "Un second scan sous un autre éclairage et d'autres angles rend la reconnaissance plus fiable. Si vous portez des lunettes, vous pouvez les retirer cette fois.",
  "Giriş ekranında şifre ya da PIN yerine yüzünüzle giriş yapın. Yüzünüz birkaç açıdan taranır; yalnızca matematiksel bir özet şifrelenerek saklanır, fotoğraf saklanmaz.": "Connectez-vous avec votre visage au lieu d'un mot de passe ou d'un PIN. Votre visage est scanné sous plusieurs angles ; seul un résumé mathématique chiffré est conservé, jamais de photo.",
  "Başınızı yavaşça daire çizerek çevirin": "Faites lentement tourner la tête en cercle", "Halka tamamlanınca yüzünüz tanıtılır": "Votre visage est enregistré lorsque l'anneau est complet",
  "Güvenlik için mevcut şifreniz": "Votre mot de passe actuel, par sécurité", "Tamamla": "Terminer", "{n} / 9 açı": "{n} / 9 angles", "Yüzünüzü tanıtın": "Enregistrez votre visage",
  "Süre doldu": "Délai expiré", "Yeniden başlatın": "Veuillez recommencer", "Bağlantı hatası": "Erreur de connexion",
  "Farklı bir yüz algılandı — yalnızca kendi yüzünüzü tanıtın": "Un autre visage a été détecté — n'enregistrez que votre propre visage", "Önce doğrudan kameraya bakın": "Regardez d'abord directement la caméra",
  "Kaydediliyor…": "Enregistrement…", "İkinci tarama tamamlandı": "Second scan terminé", "Yüzünüz tanıtıldı": "Votre visage est enregistré", "{n} açıdan kaydedildi": "Enregistré sous {n} angles",
  "İkinci taramayı yap (önerilir)": "Faire un second scan (recommandé)", "Bitti": "Terminé", "Hazır": "Prêt",
  "Yüz ile giriş sistem yöneticisi tarafından kapatılmış.": "La connexion par le visage a été désactivée par l'administrateur système.",
  "Yüz tanıma motoru bu sunucuda kurulu değil; yöneticinize başvurun.": "Le moteur de reconnaissance faciale n'est pas installé sur ce serveur ; contactez votre administrateur.",
  "Bu cihazda bir kez şifreyle giriş yaptıktan sonra giriş ekranında adınıza dokunup yüzünüzle girebilirsiniz. Yüzünüzün yalnızca şifrelenmiş matematiksel özeti saklanır; fotoğraf saklanmaz.": "Après une connexion par mot de passe sur cet appareil, touchez votre nom sur l'écran de connexion et connectez-vous avec votre visage. Seul un résumé mathématique chiffré de votre visage est conservé, jamais de photo.",
  "Yüz tanıtılmamış": "Visage non enregistré", "Yüz tanıtıldı · {n} açı": "Visage enregistré · {n} angles", "Yalnız yüz": "Visage seul", "Yüz + PIN": "Visage + PIN",
  "Önce PIN ile girişi açın": "Activez d'abord la connexion par PIN", "Yüz doğrulandıktan sonra PIN de istenecek": "Le PIN sera aussi demandé après la vérification du visage", "Yalnız yüz ile giriş": "Connexion par le visage seul",
  "Giriş kipi": "Mode de connexion", "Yüz doğrulanınca ek olarak PIN sorulur (daha güvenli)": "Après la vérification du visage, le PIN est aussi demandé (plus sûr)", "Yüz doğrulanınca doğrudan giriş": "Connexion directe dès que le visage est vérifié",
  "Yeniden tanıt": "Réenregistrer", "Yüz verisini sil": "Supprimer les données du visage",
  "Kayıtlı yüz özeti kalıcı olarak silinir; giriş ekranında yüz ile giriş kapanır. İstediğiniz zaman yeniden tanıtabilirsiniz.": "Le résumé facial enregistré est supprimé définitivement et la connexion par le visage est désactivée sur l'écran de connexion. Vous pourrez le réenregistrer à tout moment.",
  "Sil": "Supprimer", "Yüz verisi silindi": "Données du visage supprimées", "Kullanıcı bilgileri, şifre, PIN, yüz ile giriş": "Informations utilisateur, mot de passe, PIN, connexion par le visage", "Şifre kuralları, giriş, PIN ve yüz": "Règles de mot de passe, connexion, PIN et visage",
  "Güvenilir cihazda kamerayla (Face ID tarzı) giriş. Yüz özeti sunucuda şifreli saklanır; kullanıcı Kişisel Ayarlar › Hesap’tan tanıtır.": "Connexion par caméra (style Face ID) sur les appareils de confiance. Le résumé facial est stocké chiffré sur le serveur ; l'utilisateur l'enregistre dans Paramètres personnels › Compte.",
  "Yüz ile girişe izin ver": "Autoriser la connexion par le visage", "Kapatılırsa kimse yüzle giremez ve yeni yüz tanıtılamaz; mevcut kayıtlar silinmez": "Si désactivé, personne ne peut se connecter avec son visage ni en enregistrer un nouveau ; les enregistrements existants sont conservés",
  "Eşleşme eşiği": "Seuil de correspondance", "Kosinüs benzerliği × 100. 45 önerilir; düşük = daha hoşgörülü (yanlış kabul riski), yüksek = daha sıkı (ışık değişiminde ret).": "Similarité cosinus × 100. 45 recommandé ; plus bas = plus tolérant (risque de fausse acceptation), plus haut = plus strict (rejets selon l'éclairage).",
  "Canlılık adımı (baş çevirme)": "Étape de vivacité (rotation de la tête)", "Eşleşmeden sonra rastgele bir yöne hafifçe bakılması istenir; fotoğrafla kandırmayı zorlaştırır": "Après la correspondance, il est demandé de regarder légèrement dans une direction aléatoire ; complique la fraude par photo",
