  "Parametreyi sil": "Supprimer le paramètre",
  "{name} kaydı silinsin mi? Çalışan SITL etkilenmez; sonraki açılışta firmware varsayılanı kullanılır.": "Supprimer l’enregistrement {name} ? Le SITL en cours n’est pas affecté ; la valeur firmware par défaut sera utilisée au prochain démarrage.",
  "{name} silindi": "{name} supprimé",
  "Aramaya uyan parametre yok": "Aucun paramètre ne correspond à la recherche",
  "Henüz kayıtlı parametre yok. Sanal dronla uçarken HEPGO panelinden ya da Mission Planner'dan değiştirilen her parametre burada kalıcı olur; aynı dronla SITL yeniden açılınca geri yüklenir.": "Aucun paramètre enregistré. Chaque paramètre modifié depuis le panneau HEPGO ou Mission Planner pendant le vol du drone virtuel est conservé ici et restauré au redémarrage de SITL avec le même drone.",
  "Kaydedilmeyenler (oturum/simülatör ayarı ya da sayaç): {prefixes} ön ekleri ve {names}": "Non enregistrés (réglage de session/simulateur ou compteur) : préfixes {prefixes} et {names}",
  "{n} parametre içe aktarıldı, {s} atlandı": "{n} paramètres importés, {s} ignorés",
  "Mission Planner .param biçiminde indir (AD,DEĞER)": "Télécharger au format .param Mission Planner (NOM,VALEUR)",
  "Dışa aktar (.param)": "Exporter (.param)",
  "Mission Planner .param dosyasını kayıtlara ekle (hariç tutulanlar atlanır)": "Ajouter un fichier .param Mission Planner aux enregistrements (les exclus sont ignorés)",
  "İçe aktar": "Importer",
  "Kayıtlı parametre yok": "Aucun paramètre enregistré",
  "Tümünü sıfırla": "Tout réinitialiser",
  "{code} dronunun {n} kayıtlı parametresi silinsin mi? Sonraki SITL açılışı firmware varsayılanlarıyla olur. Geri alınamaz.": "Supprimer les {n} paramètres enregistrés du drone {code} ? Le prochain démarrage SITL utilisera les valeurs firmware par défaut. Irréversible.",
  "{n} parametre silindi": "{n} paramètres supprimés",
  "Sanal dronla uçuşta HEPGO panelinden ya da Mission Planner'dan değiştirilen parametreler kalıcıdır: aynı dronla SITL yeniden başlatılınca varsayilan.parm ile ve ilk kalp atışında PARAM_SET ile geri yüklenir.": "Les paramètres modifiés depuis le panneau HEPGO ou Mission Planner pendant le vol du drone virtuel sont persistants : au redémarrage de SITL avec le même drone, ils sont restaurés via varsayilan.parm et réécrits par PARAM_SET au premier battement de cœur.",
  "Yüklenemedi": "Chargement impossible",
  "SITL (araç)": "SITL (véhicule)",
  "Kayıttaki sabit kanat uçağın kalkış düzeneği: rampa ya da araç 3B sahnede kurulur; ARM, fırlatma ve bırakma aşamaları logdan (ARM anı, ilk hareket, yer hızı/irtifa) türetilir. SITL parametresi yazılmaz.": "Dispositif de décollage de l'avion à voilure fixe de l'enregistrement : la rampe ou le véhicule est construit dans la scène 3D ; les phases ARM, lancement et largage sont déduites du journal (instant ARM, premier mouvement, vitesse sol/altitude). Aucun paramètre SITL n'est écrit.",
  "SITL yer teması": "Impact au sol SITL",
