  "Henüz simülasyon kaydı yok. \"Yeni Simülasyon\" ile başlayın; oturum bitince kayıt burada görünür.": "Aucun enregistrement pour l’instant. Commencez par « Nouvelle simulation » ; l’enregistrement apparaît ici à la fin de la session.",
  "Filtreye uyan kayıt yok.": "Aucun enregistrement ne correspond au filtre.",
  "Sayfa {p} / {n}": "Page {p} / {n}",
  "Her oturumun kapanışında: özet rapor, .bin uçuş logu, ekran kaydı, son parametre dökümü ve SITL script arşivi. Parametre ve script indirme yalnız sistem sahibine (MASTER) açıktır.": "À la fin de chaque session : rapport, journal .bin, enregistrement d’écran, export des paramètres et archive des scripts SITL. Le téléchargement des paramètres et scripts est réservé au propriétaire (MASTER).",
  "Her oturumun kapanışında: özet rapor, .bin uçuş logu ve ekran kaydı. Oynat, kaydı kayıttan oynat kipinde açar.": "À la fin de chaque session : rapport, journal .bin et enregistrement d’écran. « Lire » ouvre l’enregistrement en mode relecture.",
