  // §23 güç ve yakıt (Uçuş Simülatörü)
  "Güç ve yakıt": "Puissance et carburant",
  "Motor ve batarya bütçesi: azami hız SITL fiziğine ve ArduPilot hız sınırlarına uygulanır; yakıt mesafe + gaz koluna, elektronik batarya saatlik tüketime göre azalır. Biterse yalnız kırmızı uyarı verilir, uçuş sürer. Uçuş sonunda ölçülen km/L ve ortalama W dron kaydına yazılır ve sonraki simülasyonda önerilir.": "Budget moteur et batterie : la vitesse maximale est appliquée à la physique SITL et aux limites de vitesse ArduPilot ; le carburant baisse avec la distance + les gaz, la batterie électronique avec la consommation horaire. En cas d’épuisement, seul un avertissement rouge s’affiche et le vol continue. À la fin, les km/L mesurés et les W moyens sont écrits dans la fiche du drone et proposés à la simulation suivante.",
  "Motor": "Moteur",
  "Azami hız": "Vitesse maximale",
  "Tam gazda seviye uçuş hızı (CAYMAZ 222 cc karbüratörlü motor: 45 m/s). SITL itki çarpanı + AIRSPEED_MAX/CRUISE, THR_MAX 100.": "Vitesse en palier plein gaz (CAYMAZ moteur à carburateur 222 cc : 45 m/s). Multiplicateur de poussée SITL + AIRSPEED_MAX/CRUISE, THR_MAX 100.",
  "Yakıt": "Carburant",
  "0 = yakıt göstergesi yok (elektrikli).": "0 = pas de jauge de carburant (électrique).",
  "Tüketim": "Consommation",
  "Seyirde kat edilen km başına yakıt; gaz kolu %100'de tüketim 2 katına çıkar.": "Carburant par km parcouru en croisière ; à 100 % de gaz la consommation double.",
