  "Otopilot, telemetri, servolar (servo hareketi küçük ek yük); SITL'in kendi pil göstergesi değildir.": "Autopilote, télémétrie, servos (le mouvement des servos ajoute une petite charge) ; ce n’est pas la jauge batterie de SITL.",
  "Azami hız {v} m/s ({k} km/h)": "Vitesse maximale {v} m/s ({k} km/h)",
  "stok SITL ≈ {s} m/s": "SITL d’origine ≈ {s} m/s",
