  "Batarya göstergesi kapalı": "Jauge batterie désactivée",
  "SITL ikilisi itki ölçeği (SIM_PLN_THR_MUL) desteklemiyor: azami hız yalnız ArduPilot sınırlarına uygulanır; tam gaz hızı stok fizikte ≈ {s} m/s kalır.": "Le binaire SITL ne prend pas en charge l’échelle de poussée (SIM_PLN_THR_MUL) : la vitesse maximale ne s’applique qu’aux limites ArduPilot ; plein gaz, la vitesse reste ≈ {s} m/s en physique d’origine.",
