  // --- Uçuş Simülatörü §13.1: kontrol düzeni (klasik / elevon / V-kuyruk) ---
  "Aileron + Elevatör (T-kuyruk)": "Ailerons + profondeur (empennage en T)",
  "Elevon (delta kanat)": "Élevons (aile delta)",
  "V-kuyruk (ruddervator)": "Empennage en V (ruddervator)",
  "Klasik": "Classique",
  "Elevon": "Élevon",
  "V-kuyruk": "Empennage V",
  "Kontrol düzeni": "Disposition des commandes",
  "Düzen": "Disposition",
  "Düzen sütunu": "Colonne disposition",
  "Önerilen": "Recommandé",
  "SITL modeli": "Modèle SITL",
  "kalıcı kayıt öncelikli": "enregistrement persistant prioritaire",
  "Klasik kuyruk: kanat uçlarında aileron (yatış), yatay kuyrukta elevatör (yunuslama), dikey kuyrukta rudder (sapma). SERVO1 4 · SERVO2 19 · SERVO4 21.": "Empennage classique : ailerons sur l’aile (roulis), profondeur (tangage), direction (lacet). SERVO1 4 · SERVO2 19 · SERVO4 21.",
  "Delta / uçan kanat: iki elevon hem yunuslama hem yatış (ArduPlane karışımı, MIXING_GAIN). SERVO1 78 · SERVO2 77 (REVERSED 1/1); SITL plane-elevon.": "Delta / aile volante : deux élevons pour le tangage et le roulis (mixage ArduPlane, MIXING_GAIN). SERVO1 78 · SERVO2 77 (REVERSED 1/1) ; SITL plane-elevon.",
  "V-kuyruk: iki ruddervator hem yunuslama hem sapma; kanatta aileron. SERVO1 4 · SERVO2 80 · SERVO4 79 (SERVO2 REVERSED 1); SITL plane-vtail.": "Empennage en V : deux ruddervators pour le tangage et le lacet ; ailerons sur l’aile. SERVO1 4 · SERVO2 80 · SERVO4 79 (SERVO2 REVERSED 1) ; SITL plane-vtail.",
  "Kontrol yüzeylerinin düzeni: ArduPlane SERVO işlevleri ve SITL uçak modeli buna göre kurulur, 3B'de yüzeyler buna göre oynar. Model seçilince modelin düzeni önerilir; değiştirebilirsiniz.": "Disposition des gouvernes : les fonctions SERVO d’ArduPlane et le modèle SITL en découlent ; en 3D les gouvernes bougent en conséquence. Le choix d’un modèle propose sa disposition ; modifiable.",
  "CAYMAZ delta kanat: iki elevon hem yunuslama hem yatış; ArduPlane karışımı MIXING_GAIN 0,5 (doymaz). Dronun kalıcı kaydında SERVO1/2_FUNCTION varsa (ör. CAYMAZ 4/19) kalıcı değer öncelikli; SITL modeli etkin işlevlerden seçilir ve konsola yazılır.": "Aile delta CAYMAZ : deux élevons pour le tangage et le roulis ; mixage ArduPlane MIXING_GAIN 0,5 (sans saturation). Si l’enregistrement persistant du drone contient SERVO1/2_FUNCTION (ex. CAYMAZ 4/19), il est prioritaire ; le modèle SITL suit les fonctions effectives et est noté dans la console.",
  "V-kuyruk: sağa sapma komutunda sol ruddervator arka kenarı yukarı, sağ aşağı; burun yukarı komutunda ikisi de yukarı. ArduPilot'un kendi SITL kurulumu (plane-vtail.parm) ile aynı.": "Empennage en V : sur un ordre de lacet à droite, le bord de fuite du ruddervator gauche monte et le droit descend ; à cabrer, les deux montent. Identique à la configuration SITL d’ArduPilot (plane-vtail.parm).",
  "Klasik: aileron yatış, elevatör yunuslama, rudder sapma. ArduPlane varsayılan işlevleri.": "Classique : ailerons roulis, profondeur tangage, direction lacet. Fonctions ArduPlane par défaut.",
