  "Kendinizi aramalara ve/veya mesajlara kapatabilirsiniz. Süre seçebilir, sürekli kapalı kalabilir ya da yalnız mesai sonrasında kapanabilirsiniz; süre dolunca otomatik açılır.": "Vous pouvez vous rendre indisponible pour les appels et/ou messages. Choisissez une durée, restez indisponible en permanence ou seulement après les heures de travail ; tout se rouvre automatiquement à la fin.",
  "“Sürekli”: siz açana kadar · “Mesai sonrası”: mesai bitiminden ertesi mesai başlangıcına, hafta sonu tüm gün": "« En permanence » : jusqu’à ce que vous le désactiviez · « Après les heures de travail » : de la fin du travail au début suivant, toute la journée le week-end",
