  "Simülasyonda havada sürekli uçan hedefler: her biri seçtiğiniz irtifada, verdiğiniz çapta dairesel yörüngede uçar (SITL'siz, sunucuda kinematik; Mission Planner haritasında ADSB trafiği olarak görünür). Dronunuz bir hedefe önleme yarıçapı içinde yaklaşınca \"önleme\" sayılır; raporda sayı ve süre yer alır.": "Des cibles qui volent en continu : chacune suit une orbite circulaire à l’altitude et au diamètre choisis (sans SITL, cinématique côté serveur ; trafic ADSB sur la carte Mission Planner). Quand votre drone entre dans le rayon d’interception, c’est une « interception » ; le rapport donne nombre et durée.",
